import novamind_api as nm

print("=== MACRO ===")
mo = nm.market.get_market_overview()
macro = mo.get('macroeconomic', {})
print("PMI:", macro.get('pmi_value'), "phase:", macro.get('cycle_phase'))

print("\n=== S2 GROUP INSIGHTS ===")
try:
    gi = nm.market.get_group_insights(group_id="S2")
    for k, v in gi.items():
        if isinstance(v, (dict, list)):
            print(f"{k}:")
            if isinstance(v, dict):
                for k2, v2 in v.items():
                    print(f"    {k2}: {v2}")
            else:
                for it in v[:10]:
                    print(f"    {it}")
        else:
            print(f"{k}: {v}")
except Exception as e:
    print("ERR", e)

print("\n=== CURRENT LEAD PROMO / PROMO STATE ===")
try:
    lp = nm.marketing.set_lead_promotion()
    print("lead_promo:", lp)
except Exception as e:
    print("lead_promo read err:", e)

print("\n=== SOCIAL POSTS 7d (sentiment/competitor scan) ===")
sp = nm.analytics.get_social_posts(days=7, limit=25)
posts = sp.get('posts', []) if isinstance(sp, dict) else sp
for p in posts:
    txt = (p.get('content','') or '')[:155]
    print(f"  [{p.get('group_id','?')}] {txt}")
